/**
 * HTML written in the Shopify admin (product and collection descriptions), made safe to insert into the site. Store
 * staff and apps that can edit products are not trusted to run script on the storefront, where customer sessions
 * live: script, event handlers and script URLs are removed, and everything that only shows content (markup, styles,
 * images, links, video embeds) is kept as written.
 */

/** Elements that run code or change how the page loads. Removed with their content. */
const BLOCKED_ELEMENTS = new Set([
  'SCRIPT',
  'OBJECT',
  'EMBED',
  'BASE',
  'META',
  'LINK',
  'NOSCRIPT',
  'TEMPLATE',
  // SVG animation can set an attribute such as href to a script URL after the attributes were checked.
  'ANIMATE',
  'SET',
]);
/** Attributes whose value is fetched or navigated to. */
const URL_ATTRIBUTES = new Set(['href', 'src', 'action', 'formaction', 'xlink:href', 'poster', 'data', 'background']);
/** Schemes that run code when navigated to. */
const SCRIPT_URL = /^\s*(javascript|vbscript|data):/i;
/** `data:` stays allowed for images, which only decode pixels. */
const DATA_IMAGE = /^\s*data:image\/(png|gif|jpeg|webp|avif);/i;

/** Browsers ignore control characters and spaces in a URL's scheme (`java	script:`), so the check does too. */
// eslint-disable-next-line no-control-regex -- control characters are exactly what browsers skip in a scheme
const IGNORED_IN_SCHEME = /[�- ]/g;

/** @param {Element} element @param {Attr} attribute */
function isUnsafeAttribute(element, attribute) {
  const name = attribute.name.toLowerCase();
  if (name.startsWith('on') || name === 'srcdoc') return true;
  const url = attribute.value.replace(IGNORED_IN_SCHEME, '');
  if (!URL_ATTRIBUTES.has(name) || !SCRIPT_URL.test(url)) return false;
  return !(element.tagName === 'IMG' && name === 'src' && DATA_IMAGE.test(url));
}

/** @param {ParentNode} root */
function clean(root) {
  for (const element of [...root.querySelectorAll('*')]) {
    if (BLOCKED_ELEMENTS.has(element.tagName.toUpperCase())) {
      element.remove();
      continue;
    }
    for (const attribute of [...element.attributes]) {
      if (isUnsafeAttribute(element, attribute)) element.removeAttribute(attribute.name);
    }
  }
}

/**
 * Store HTML as a fragment, with script removed.
 *
 * @param {string | null | undefined} html
 * @param {Document} [document] The document the fragment is for.
 * @returns {DocumentFragment}
 */
export function storeHtmlFragment(html, document = globalThis.document) {
  const template = document.createElement('template');
  // A <template>'s content is parsed inert: nothing in it loads or runs before it is cleaned.
  // eslint-disable-next-line no-restricted-syntax -- parsing into an inert template is the sanctioned way in
  template.innerHTML = html ?? '';
  clean(template.content);
  return template.content;
}
